package com.andye.warmod.block;import com.andye.warmod.block.entity.PhalanxBlockEntity;import com.andye.warmod.phalanx.PhalanxManager;import java.util.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.context.BlockPlaceContext;import net.minecraft.world.level.block.Block;import net.minecraft.world.phys.AABB;
public final class PhalanxTurretBlockItem extends BlockItem{public PhalanxTurretBlockItem(Properties p){super(ModBlocks.PHALANX_TURRET,p);}@Override public InteractionResult place(BlockPlaceContext c){if(c.getLevel().isClientSide())return InteractionResult.SUCCESS;if(!(c.getLevel()instanceof ServerLevel level))return InteractionResult.FAIL;Player player=c.getPlayer();BlockPos controller=c.getClickedPos();Direction facing=player==null?Direction.NORTH:player.getDirection().getOpposite();if(!PhalanxManager.canPlace(level))return fail(player,"Phalanx limit reached");for(var part:PhalanxPart.values()){BlockPos p=controller.offset(part.offset());if(level.isOutsideBuildHeight(p)||!level.getWorldBorder().isWithinBounds(p)||!level.getBlockState(p).canBeReplaced()||level.getBlockEntity(p)!=null||(player!=null&&!level.mayInteract(player,p))||!level.getEntities(null,new AABB(p)).isEmpty())return fail(player,"Cannot place complete 2x2x2 Phalanx here");}ArrayList<BlockPos> placed=new ArrayList<>();try{for(var part:PhalanxPart.values()){BlockPos p=controller.offset(part.offset());if(!level.setBlock(p,ModBlocks.PHALANX_TURRET.defaultBlockState().setValue(PhalanxTurretBlock.PART,part).setValue(PhalanxTurretBlock.FACING,facing),Block.UPDATE_ALL))throw new IllegalStateException();placed.add(p);}if(!(level.getBlockEntity(controller)instanceof PhalanxBlockEntity be))throw new IllegalStateException();be.initialize(player,facing);if(!PhalanxManager.register(level,be))throw new IllegalStateException();c.getItemInHand().consume(1,player);return InteractionResult.SUCCESS_SERVER;}catch(RuntimeException ex){for(BlockPos p:placed)level.setBlock(p,net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),Block.UPDATE_ALL);return fail(player,"Phalanx placement failed atomically");}}private static InteractionResult fail(Player p,String m){if(p!=null)p.sendSystemMessage(Component.literal(m));return InteractionResult.FAIL;}}
